# c09 補給都市の攻防 - 盤面に散る補給都市を東西から奪い合う。
# 首都は左右の端。以前は斜めの帯で左上と右下がほぼ未使用だったため作り直した。
# 野戦飛行場(A)は航空機の補給・修理・進化はできるが生産はできない。
[map]
name             = 補給都市の攻防
width            = 46
height           = 25
turns            = 84
timeout_winner   = -1
funds0           = 3000
funds1           = 3000
# 拠点確保による勝利条件。拠点が24個→32個に増えたので比例させた（旧 22/24）
